<template>
  <div class="space-y-4">
    <div class="page-head"><div><h1>Management Controls</h1><p>Collections, exports and an auditable history of important business actions.</p></div></div>
    <div class="grid grid-cols-1 gap-4 xl:grid-cols-[1.15fr_1fr]">
      <section class="card p-5">
        <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-sm font-extrabold">Collection follow-ups</h2><p class="mt-1 text-[11px] text-slate-400">Plan and close customer collection activities.</p></div><button class="btn btn-primary" @click="openFollowup">+ Follow-up</button></div>
        <div class="table-wrap mt-4"><table class="data-table"><thead><tr><th>Date</th><th>Client</th><th>Invoice</th><th>Channel</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="f in followups" :key="f.id"><td>{{f.follow_up_date}}</td><td>{{f.client?.name}}</td><td>{{f.invoice?.invoice_number || 'Account'}}</td><td class="capitalize">{{f.channel}}</td><td><span class="status" :class="f.status==='completed'?'status-success':'status-warning'">{{f.status}}</span></td><td class="text-right"><button v-if="f.status!=='completed'" class="btn btn-soft" @click="complete(f)">Complete</button></td></tr><tr v-if="!followups.length"><td colspan="6"><div class="empty">No follow-ups planned.</div></td></tr></tbody></table></div>
      </section>
      <section class="card p-5"><h2 class="text-sm font-extrabold">Data exports</h2><p class="mt-1 text-[11px] text-slate-400">Download operational data as CSV for Excel and reconciliation.</p><div class="mt-4 grid grid-cols-2 gap-3"><button v-for="x in exports" :key="x.type" class="btn btn-soft justify-start" @click="download(x.type)">{{x.label}}</button></div><p class="mt-4 text-[10px] text-slate-400">Exports respect the authenticated company context.</p></section>
    </div>
    <section class="card overflow-hidden"><div class="px-5 py-4 border-b border-slate-100 dark:border-slate-800"><h2 class="text-sm font-extrabold">Audit trail</h2><p class="mt-1 text-[11px] text-slate-400">Important changes made by users.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td>{{date(a.created_at)}}</td><td>{{a.user?.name || 'System'}}</td><td><span class="status status-neutral capitalize">{{a.action}}</span></td><td>{{a.auditable_type?.split('\\').pop()}} #{{a.auditable_id}}</td><td><span class="text-[10px] text-slate-400">{{summary(a)}}</span></td></tr><tr v-if="!audits.length"><td colspan="5"><div class="empty">No audit events yet.</div></td></tr></tbody></table></div></section>
    <AppModal :open="modal" title="Plan collection follow-up" @close="modal=false"><form class="space-y-4" @submit.prevent="saveFollowup"><div><label class="label">Client</label><select v-model="form.client_id" class="input" required><option value="">Select client</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Invoice (optional)</label><select v-model="form.invoice_id" class="input"><option value="">Account-level follow-up</option><option v-for="i in clientInvoices" :key="i.id" :value="i.id">{{i.invoice_number}} · {{money(i.balance)}}</option></select></div><div class="grid grid-cols-2 gap-3"><div><label class="label">Date</label><input v-model="form.follow_up_date" type="date" class="input" required></div><div><label class="label">Channel</label><select v-model="form.channel" class="input"><option>phone</option><option>email</option><option>sms</option><option>whatsapp</option><option>visit</option><option>other</option></select></div></div><div><label class="label">Notes</label><textarea v-model="form.notes" class="input min-h-24" placeholder="Promise to pay, contact outcome, next action..."></textarea></div><div class="action-row justify-end"><button type="button" class="btn btn-soft" @click="modal=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{saving?'Saving...':'Plan follow-up'}}</button></div></form></AppModal>
  </div>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {api,apiError} from '../../services/api';
import {formatDateTime} from '../../utils/date';import {useToast} from '../../stores/toast';import {useConfirm} from '../../stores/confirm';import AppModal from '../../components/AppModal.vue';
const toast=useToast(),{ask:confirm}=useConfirm();const followups=ref<any[]>([]),audits=ref<any[]>([]),clients=ref<any[]>([]),invoices=ref<any[]>([]),modal=ref(false),saving=ref(false);const form=ref<any>({client_id:'',invoice_id:'',follow_up_date:new Date().toISOString().slice(0,10),channel:'phone',notes:''});const exports=[{type:'sales',label:'Sales CSV'},{type:'invoices',label:'Invoices CSV'},{type:'payments',label:'Payments CSV'},{type:'expenses',label:'Expenses CSV'}];const clientInvoices=computed(()=>invoices.value.filter(i=>String(i.client_id)===String(form.value.client_id)&&Number(i.balance)>0));
function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function date(v:any){return formatDateTime(v)}function summary(a:any){const n=a.new_values||{};return n._reason||n.name||n.invoice_number||n.payment_number||n.sale_number||'Record changed'}
async function load(){try{const [f,a,c,i]=await Promise.all([api.get('/management/followups'),api.get('/management/audit'),api.get('/clients',{params:{per_page:100}}),api.get('/invoices',{params:{per_page:200,status:'issued'}})]);followups.value=f.data.data||f.data;audits.value=a.data.data||a.data;clients.value=c.data.data||c.data;invoices.value=i.data.data||i.data}catch(e){toast.error('Unable to load controls',apiError(e))}}
function openFollowup(){form.value={client_id:'',invoice_id:'',follow_up_date:new Date().toISOString().slice(0,10),channel:'phone',notes:''};modal.value=true}watch(()=>form.value.client_id,()=>{form.value.invoice_id=''})
async function saveFollowup(){saving.value=true;try{await api.post('/management/followups',form.value);toast.success('Follow-up planned','Collection activity has been scheduled.');modal.value=false;await load()}catch(e){toast.error('Could not plan follow-up',apiError(e))}finally{saving.value=false}}
async function complete(f:any){if(!(await confirm({title:'Complete follow-up?',message:'This will mark the collection activity as completed.',confirmText:'Complete',danger:false})))return;try{await api.patch(`/management/followups/${f.id}/complete`);toast.success('Follow-up completed','The collection activity has been closed.');await load()}catch(e){toast.error('Action failed',apiError(e))}}
async function download(type:string){try{const r=await api.get(`/management/export/${type}`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=`mauzohub-${type}.csv`;a.click();URL.revokeObjectURL(url);toast.success('Export ready',`${type} data was downloaded.`)}catch(e){toast.error('Export failed',apiError(e))}}
onMounted(load)
</script>
